  var CSS = ".kge-wrap{--kge-accent:#2563eb;--kge-accent-weak:#eff4ff;--kge-fg:#1f2733;--kge-fg-muted:#647084;--kge-bg:#fff;--kge-bg-alt:#f7f9fc;--kge-border:#e4e8ef;--kge-border-strong:#cfd6e2;--kge-danger:#dc2626;--kge-success:#16a34a;--kge-radius:12px;--kge-radius-sm:8px;--kge-shadow:0 1px 2px rgba(16,24,40,.04),0 8px 24px rgba(16,24,40,.06);--kge-row-h:44px;--kge-speed:.15s;color:var(--kge-fg);border:1px solid var(--kge-border);border-radius:var(--kge-radius);background:var(--kge-bg);box-shadow:var(--kge-shadow);overflow:clip;margin:0 0 1rem}"
